import { render } from '@solidjs/web';
import { createSignal, createEffect } from 'solid-js';

function App() {
  const [a, setA] = createSignal(1);
  const [b, setB] = createSignal(1);
  createEffect(
    () => [a(), b()],
    (values) => console.log(values),
  );
  return (
    <>
      <button onClick={() => setA((value) => value + 1)}>
        Increment A: {a()}
      </button>
      <button onClick={() => setB((value) => value + 1)}>
        Increment B: {b()}
      </button>
    </>
  );
}

render(() => <App />, document.getElementById('app'));

import { render } from '@solidjs/web';
import { createSignal, createEffect } from 'solid-js';

function App() {
  const [a, setA] = createSignal(1);
  const [b, setB] = createSignal(1);
  createEffect(
    a,
    (value) => console.log('A changed:', value, 'B snapshot:', b()),
    { defer: true },
  );
  return (
    <>
      <button onClick={() => setA((value) => value + 1)}>
        Increment A: {a()}
      </button>
      <button onClick={() => setB((value) => value + 1)}>
        Increment B: {b()}
      </button>
    </>
  );
}

render(() => <App />, document.getElementById('app'));
